113	    public static final class GetProgramArgs extends NativeFn0 {
114	        static volatile List<String> args = null;
115	        // Must be volatile.  We're initing in one thread, running in another.
116	        // Also we're now double-checked since we must initialize lazily after
117	        // the universe has started up and is in a happy state.
118	        static volatile FValue convertedArgs = null;
119	
120	        // See also NonPrimitive.buildEnvFromParams.
121	        public static void registerProgramArgs(List<String> args) {
122	            GetProgramArgs.convertedArgs = null;
123	            GetProgramArgs.args = args;
124	        }
125	
126	        private static FValue grindProgramArgs() {
127	            FType stringType = FString.EMPTY.type();
128	            int[] natParams = new int[1];
129	            natParams[0] = args.size();
130	            Simple_fcn mkArr = Glue.instantiateGenericConstructor(Driver.getFortressLibrary(),
131	                                                                  WellKnownNames.varargsFactoryName,
132	                                                                  stringType,
133	                                                                  natParams);
134	            FValue result = mkArr.applyToArgs();
135	            if (!(result instanceof PrimImmutableArray.PrimImmutableArrayObject)) {
136	                return bug("registerProgramArgs: unexpected varargs array type " + result);
137	            }
138	            PrimImmutableArray.PrimImmutableArrayObject arr = (PrimImmutableArray.PrimImmutableArrayObject) result;
139	            for (int i = 0; i < args.size(); i++) {
140	                arr.init(i, FString.make(args.get(i)));
141	            }
142	            return result;
143	        }
144	
145	        protected FValue applyToArgs() {
146	            if (convertedArgs == null) {
147	                if (args == null) {
148	                    return bug("No program args were registered by calling " +
149	                               "StringPrim.GetProgramArgs.registerProgramArgs");
150	                }
151	                synchronized (args) {
152	                    if (convertedArgs == null) {
153	                        convertedArgs = grindProgramArgs();
154	                    }
155	                }
156	            }
157	            return convertedArgs;
158	        }
159	    }
